// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.stt.whisperimport timber.log.Timberimport com.roshan.persona.voice.capture.AudioCapturePipeline/** * NOUS — Whisper.cpp JNI Bridge. * * Kotlin-side JNI declarations for the whisper.cpp native library. The C++ * implementation lives in `:native:whisper/src/main/cpp/jarvis_whisper.cpp` * (loaded as `libjarvis_whisper.so`). * * ## v2 Features (per §6 Whisper.cpp JNI Bridge) * *   - 16 kHz / 16-bit mono PCM input (matches [AudioCapturePipeline] format) *   - Streaming partial results via JNI callback (segment-by-segment) *   - Multi-threaded CPU inference (1-4 threads, device-aware) *   - Vulkan GPU acceleration (optional, probed at runtime) *   - Barge-in via `g_should_stop` atomic flag (instant cancel) *   - Speed-up mode (1.5-2× faster, slightly lower accuracy) *   - Translation mode (any language → English) *   - Model metadata query (architecture, quantization, parameters) * * ## Native Library Loading * * Loaded lazily on first use. If the library is not present (dev build * without pre-built .so), [ensureLoaded] returns false and the * [WhisperSttEngine] falls back to emitting [SttResult.Error] with * `Reason.MODEL_CRASH` — the [StreamingSttEngine] then tries Vosk. * * ## Lifecycle * * 1. [nativeInitContext] — load model into memory (~2-5 s for base.en) * 2. [nativeFull] or [nativeFullStream] — transcribe audio * 3. [nativeFreeContext] — release model (~50 ms) * * ## Thread Safety * * The native context pointer is *not* thread-safe. The [WhisperSttEngine] * wraps every call in a mutex so concurrent recognitions are serialized. * Cancellation ([nativeStopRecognition]) is thread-safe — it sets an atomic * flag that the native code checks between tokens. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§6 Speech-to-Text — Whisper.cpp JNI Bridge</a> */object WhisperJni {    private const val TAG = "WhisperJni"    @Volatile    private var loaded: Boolean = false    @Volatile    private var loadFailed: Boolean = false    /**     * Load the native library. Safe to call multiple times.     *     * @return true if loaded successfully, false if library not available     *         (dev build without pre-built .so, or unsupported ABI).     */    @Synchronized    fun ensureLoaded(): Boolean {        if (loaded) return true        if (loadFailed) return false        return try {            System.loadLibrary("jarvis_whisper")            loaded = true            Timber.tag(TAG).i("Native library 'jarvis_whisper' loaded.")            true        } catch (e: UnsatisfiedLinkError) {            loadFailed = true            Timber.tag(TAG).w("libjarvis_whisper.so not available — Whisper STT disabled.", e)            false        } catch (e: SecurityException) {            loadFailed = true            Timber.tag(TAG).w("Security manager blocked library load.", e)            false        }    }    /** Whether the native library is loaded. */    fun isLoaded(): Boolean = loaded    /** Reset load state. For tests only. */    internal fun resetLoadState() {        loaded = false        loadFailed = false    }    // ─── JNI Declarations ───────────────────────────────────────────    /**     * Initialize a whisper.cpp context with the given model.     *     * @param modelPath    absolute path to the .gguf model file     *                     (e.g. `/data/.../ggml-base.en.bin` or     *                     `.../ggml-small-q5_1.bin`)     * @param useGpu       whether to use Vulkan GPU acceleration     * @param threads      number of CPU threads (1-4; device-aware)     * @return native context pointer (>0) on success, 0 on failure     */    @JvmStatic    external fun nativeInitContext(        modelPath: String,        useGpu: Boolean,        threads: Int,    ): Long    /**     * CRITICAL FIX #38: Safe wrapper around nativeInitContext with validation.     */    fun safeInitContext(        modelPath: String,        useGpu: Boolean,        threads: Int,    ): Long {        // Validate model path        if (modelPath.isBlank()) {            Timber.tag(TAG).e("modelPath is blank")            return 0L        }                // Validate thread count (1-4 for CPU, 1-2 for GPU)        val safeThreads = threads.coerceIn(1, if (useGpu) 4 else 8)        if (safeThreads != threads) {            Timber.tag(TAG).w("Thread count $threads clamped to $safeThreads")        }                // Check if file exists        val file = java.io.File(modelPath)        if (!file.exists()) {            Timber.tag(TAG).e("Model file does not exist: $modelPath")            return 0L        }                // Check file size (model should be at least 1MB)        if (file.length() < 1024 * 1024) {            Timber.tag(TAG).w("Model file suspiciously small: ${file.length()} bytes")        }                return nativeInitContext(modelPath, useGpu, safeThreads)    }    /**     * Free a whisper.cpp context. Safe to call with ptr=0 or already-freed ptr.     *     * @param contextPtr native context pointer from [nativeInitContext]     */    @JvmStatic    external fun nativeFreeContext(contextPtr: Long)    /**     * Transcribe a complete audio buffer (non-streaming).     *     * Use this when you already have the full utterance buffered (e.g. after     * VAD detected end-of-turn). For live partial results during speech, use     * [nativeFullStream] instead.     *     * @param contextPtr native context pointer     * @param samples    16 kHz, 16-bit mono PCM samples     * @param language   ISO 639-1 code ("en", "hi", "auto" for auto-detect)     * @param translate  if true, translate non-English speech to English text     * @param speedUp    if true, enable speed-up mode (1.5-2× faster, slightly     *                    lower accuracy)     * @return transcribed text, or empty string on failure     */    @JvmStatic    external fun nativeFull(        contextPtr: Long,        samples: ShortArray,        language: String,        translate: Boolean,        speedUp: Boolean,    ): String    /**     * CRITICAL FIX #39: Safe wrapper around nativeFull with validation.     */    fun safeFull(        contextPtr: Long,        samples: ShortArray,        language: String,        translate: Boolean,        speedUp: Boolean,    ): String {        if (contextPtr <= 0) {            Timber.tag(TAG).e("Invalid contextPtr: $contextPtr")            return ""        }                if (samples.isEmpty()) {            Timber.tag(TAG).w("Empty samples array")            return ""        }                // Validate language code format (ISO 639-1 or "auto")        val safeLanguage = if (language.isBlank() || language == "auto") "auto"                            else language.lowercase().trim()                return nativeFull(contextPtr, samples, safeLanguage, translate, speedUp)    }    /**     * Transcribe with streaming segment callback.     *     * The native code calls [onPartial] for each new partial segment as it's     * recognized (every ~200-500 ms). When the entire buffer is processed,     * the final full text is returned.     *     * @param contextPtr native context pointer     * @param samples    16 kHz, 16-bit mono PCM samples     * @param language   ISO 639-1 code or "auto"     * @param translate  translate to English     * @param speedUp    enable speed-up mode     * @param onPartial  callback (partialText: String) → called from native     *                    thread for each segment. Must not block.     * @return final full text (all segments concatenated), or empty string     *         on failure     */    @JvmStatic    external fun nativeFullStream(        contextPtr: Long,        samples: ShortArray,        language: String,        translate: Boolean,        speedUp: Boolean,        onPartial: (String) -> Unit,    ): String    /**     * Stop in-progress recognition (barge-in). Sets `g_should_stop` atomic     * flag checked between tokens. Returns immediately — the actual native     * call (in [nativeFull] / [nativeFullStream]) will return shortly after.     *     * Thread-safe — can be called from any thread.     *     * @param contextPtr native context pointer     */    @JvmStatic    external fun nativeStopRecognition(contextPtr: Long)    /**     * Get model metadata (architecture, quantization, parameters, language).     *     * @param modelPath absolute path to the .gguf/.bin model file     * @return JSON string with metadata, or empty string on failure     */    @JvmStatic    external fun nativeGetModelInfo(modelPath: String): String    /**     * Check if Vulkan GPU is available on this device.     *     * @return true if GPU acceleration is possible (does NOT guarantee the     *         loaded model will fit in VRAM)     */    @JvmStatic    external fun nativeIsGpuAvailable(): Boolean    /**     * Get available GPU VRAM in MB. Returns 0 if no GPU.     *     * Used by [WhisperModelSelector] to decide whether to load the larger     * `small` model (250 MB) vs the smaller `base.en` (75 MB).     */    @JvmStatic    external fun nativeGetGpuVramMb(): Int    /**     * Get whisper.cpp version string (for diagnostics / crash reports).     */    @JvmStatic    external fun nativeGetVersion(): String}